-- Local/development rollback only. Fixed seed identities; no external delivery.
begin;
create temp table ns_checks(name text primary key);grant select,insert on ns_checks to authenticated,anon,service_role;
create function pg_temp.ok(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAILED %',label;end if;insert into pg_temp.ns_checks values(label);end$$;
create function pg_temp.denied(sql text,code text,label text) returns void language plpgsql as $$declare caught text;begin begin execute sql;exception when others then get stacked diagnostics caught=returned_sqlstate;end;perform pg_temp.ok(caught is not distinct from code,label||coalesce(' ['||caught||']',' [no error]'));end$$;
create function pg_temp.claim(n integer) returns void language sql as $$select set_config('request.jwt.claims',jsonb_build_object('iss','https://gmvouqgjbtbkbhrdruzu.supabase.co/auth/v1','aud','authenticated','role','authenticated','sub','10000000-0000-0000-0000-'||lpad(n::text,12,'0'))::text,true)$$;
select pg_temp.ok(bool_and(relrowsecurity),'all Step07 tables RLS') from pg_class where oid in ('public.notifications'::regclass,'public.notification_preferences'::regclass,'public.support_tickets'::regclass,'public.support_messages'::regclass,'private.support_operators'::regclass,'private.organization_support_staff'::regclass,'private.notification_events'::regclass,'private.push_subscriptions'::regclass,'private.notification_deliveries'::regclass,'private.support_audit'::regclass,'private.support_requests'::regclass);
select pg_temp.ok(not has_function_privilege('authenticated','public.notification_worker(text,jsonb)','execute'),'student cannot dispatch');
select pg_temp.ok(not has_function_privilege('authenticated','private.emit_notification(text,text,uuid,uuid,uuid[])','execute'),'student cannot invent events');
select pg_temp.ok(not has_table_privilege('authenticated','private.support_operators','insert'),'no self operator provisioning');
select pg_temp.ok(not has_table_privilege('authenticated','private.organization_support_staff','insert'),'no self support assignment');
select pg_temp.ok(not has_function_privilege('authenticated','public.create_organization(text,text)','execute'),'organization security preserved');
select pg_temp.ok(bool_and(proconfig=array['search_path=""']),'all new definer search paths fixed') from pg_proc where pronamespace='private'::regnamespace and proname in ('support_staff_for','support_access','support_command','notification_command','notification_worker','emit_notification');
select set_config('ns.initial_unread',(select count(*) from public.notifications where recipient_id='10000000-0000-0000-0000-000000000005' and in_app and read_at is null)::text,true);
select set_config('ns.initial_lessons',(select count(*) from public.notifications where event_type='lesson_published')::text,true);
select set_config('ns.initial_approved',(select count(*) from public.notifications where event_type='account_approved')::text,true);
set local role anon;
select pg_temp.denied($q$select public.support_command('list')$q$,'42501','anonymous support denied');
select pg_temp.denied($q$select public.notification_command('list')$q$,'42501','anonymous notifications denied');
reset role;select pg_temp.claim(5);set local role authenticated;
select pg_temp.denied($q$insert into public.notifications(event_id,recipient_id,event_type) values(gen_random_uuid(),gen_random_uuid(),'support_reply')$q$,'42501','direct notification insert denied');
select pg_temp.denied($q$select public.support_command('create',null,null,gen_random_uuid(),'{"organizationId":"20000000-0000-0000-0000-000000000002","category":"video","subject":"Forbidden","body":"hello"}')$q$,'42501','student tenant injection denied');
select set_config('ns.request',gen_random_uuid()::text,true);
select set_config('ns.ticket',(public.support_command('create',null,null,current_setting('ns.request')::uuid,'{"organizationId":"20000000-0000-0000-0000-000000000001","category":"video","subject":"Playback issue","body":"<script>alert(1)</script>"}')->>'id'),true);
select pg_temp.ok(public.support_command('create',null,null,current_setting('ns.request')::uuid,'{"organizationId":"20000000-0000-0000-0000-000000000001","category":"video","subject":"Playback issue","body":"<script>alert(1)</script>"}')->>'id'=current_setting('ns.ticket'),'duplicate create returns original');
select pg_temp.ok((select count(*)=1 from public.support_tickets),'duplicate request does not duplicate ticket');
select pg_temp.denied($q$select public.support_command('create',null,null,current_setting('ns.request')::uuid,'{"category":"other","subject":"Changed","body":"Changed"}')$q$,'23514','idempotency payload mismatch denied');
select pg_temp.ok(public.support_command('get',current_setting('ns.ticket')::uuid)#>>'{messages,0,body}'='<script>alert(1)</script>','stored content is text not interpreted markup');
select pg_temp.ok((public.support_command('get',current_setting('ns.ticket')::uuid)#>>'{ticket,response_due_at}')::timestamptz>clock_timestamp()+interval '47 hours','actual response deadline persisted');
select pg_temp.denied($q$select public.support_command('assign',current_setting('ns.ticket')::uuid,0,gen_random_uuid(),'{"userId":"10000000-0000-0000-0000-000000000005"}')$q$,'42501','student cannot self assign');
select pg_temp.claim(6);
select pg_temp.ok((select count(*)=0 from public.support_tickets),'peer tickets hidden');
select pg_temp.denied($q$select public.support_command('get',current_setting('ns.ticket')::uuid)$q$,'42501','peer RPC denied');
select pg_temp.claim(3);
select pg_temp.ok((select count(*)=0 from public.support_messages),'other organization messages hidden');
select pg_temp.denied($q$select public.support_command('get',current_setting('ns.ticket')::uuid)$q$,'42501','other owner denied');
select pg_temp.claim(2);
select pg_temp.denied($q$select public.support_command('get',current_setting('ns.ticket')::uuid)$q$,'42501','teacher not automatically a support operator');
reset role;
insert into private.organization_support_staff(organization_id,user_id) values('20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000002');
set local role authenticated;
select pg_temp.ok((public.support_command('get',current_setting('ns.ticket')::uuid)->>'staff')::boolean,'explicit organization support assignment works');
select public.support_command('reply',current_setting('ns.ticket')::uuid,0,gen_random_uuid(),'{"body":"Please retry playback."}');
select pg_temp.ok(public.support_command('get',current_setting('ns.ticket')::uuid)#>>'{ticket,first_staff_response_at}' is not null,'first response recorded');
select pg_temp.ok(public.support_command('get',current_setting('ns.ticket')::uuid)#>>'{ticket,response_due_at}' is null,'staff response clears waiting deadline');
select pg_temp.denied($q$select public.support_command('reply',current_setting('ns.ticket')::uuid,0,gen_random_uuid(),'{"body":"Stale"}')$q$,'PT409','stale reply rejected');
select pg_temp.claim(5);
select pg_temp.ok((public.notification_command('list')->>'unread')::int=current_setting('ns.initial_unread')::int+1,'support reply unread event generated');
select pg_temp.ok(public.notification_command('list')#>>'{rows,0,link}'='/support?ticket='||current_setting('ns.ticket'),'authorized generated support link');
select set_config('ns.notification',public.notification_command('list')#>>'{rows,0,id}',true);
select public.notification_command('read',jsonb_build_object('id',current_setting('ns.notification')));
select pg_temp.ok((public.notification_command('list')->>'unread')::int=current_setting('ns.initial_unread')::int,'individual mark read');
select public.notification_command('unread',jsonb_build_object('id',current_setting('ns.notification')));
select pg_temp.ok((public.notification_command('list')->>'unread')::int=current_setting('ns.initial_unread')::int+1,'individual mark unread');
select pg_temp.claim(6);
select public.notification_command('read',jsonb_build_object('id',current_setting('ns.notification')));
select pg_temp.ok((select count(*)=0 from public.notifications where id=current_setting('ns.notification')::uuid),'other student notification hidden');
select pg_temp.claim(5);
select pg_temp.ok((public.notification_command('list')->>'unread')::int=current_setting('ns.initial_unread')::int+1,'peer cannot mutate unread count');
select public.notification_command('read-all');
select pg_temp.ok((public.notification_command('list')->>'unread')::int=0,'bulk mark read');
select public.notification_command('preference','{"event":"support_reply","inApp":false,"push":false}');
select pg_temp.denied($q$select public.notification_command('preference','{"event":"invalid","inApp":true,"push":false}')$q$,'23514','unknown event rejected');
select pg_temp.denied($q$select public.notification_command('subscribe','{"endpoint":"https://localhost/private","p256dh":"bad","auth":"bad"}')$q$,'23514','push SSRF denied');
select public.notification_command('subscribe',jsonb_build_object('endpoint','https://fcm.googleapis.com/fcm/send/synthetic-test','p256dh',repeat('a',87),'auth',repeat('b',22)));
select pg_temp.claim(6);
select pg_temp.denied($q$select public.notification_command('subscribe',jsonb_build_object('endpoint','https://fcm.googleapis.com/fcm/send/synthetic-test','p256dh',repeat('a',87),'auth',repeat('b',22)))$q$,'42501','subscription account takeover denied');
select pg_temp.claim(5);
select public.support_command('status',current_setting('ns.ticket')::uuid,1,gen_random_uuid(),'{"status":"RESOLVED"}');
select public.support_command('reply',current_setting('ns.ticket')::uuid,2,gen_random_uuid(),'{"body":"The problem persists"}');
select pg_temp.ok(public.support_command('get',current_setting('ns.ticket')::uuid)#>>'{ticket,status}'='OPEN','student reply reopens closed ticket');
reset role;
select pg_temp.ok((select count(*)=4 from private.support_audit),'immutable mutation history recorded');
select pg_temp.ok((select count(*)=1 from private.notification_events where event_type='support_reply'),'reply event not duplicated');
update public.lessons set status='draft' where id='50000000-0000-0000-0000-000000000001';
update public.lessons set status='published' where id='50000000-0000-0000-0000-000000000001';
select pg_temp.ok((select count(*)=current_setting('ns.initial_lessons')::int+2 from public.notifications where event_type='lesson_published'),'published lesson fanout reaches both enrolled offerings');
update public.lessons set title=title where id='50000000-0000-0000-0000-000000000001';
select pg_temp.ok((select count(*)=current_setting('ns.initial_lessons')::int+2 from public.notifications where event_type='lesson_published'),'metadata edit does not notify again');
select private.emit_notification('rollback-only-event','account_approved',null,'10000000-0000-0000-0000-000000000005',array['10000000-0000-0000-0000-000000000005'::uuid]);
select private.emit_notification('rollback-only-event','account_approved',null,'10000000-0000-0000-0000-000000000005',array['10000000-0000-0000-0000-000000000005'::uuid]);
select pg_temp.ok((select count(*)=current_setting('ns.initial_approved')::int+1 from public.notifications where event_type='account_approved'),'event key idempotent');
select pg_temp.claim(5);set local role authenticated;
select pg_temp.ok((select count(*)=0 from jsonb_array_elements(public.notification_command('list')->'rows') n where n->>'event_type'='account_approved' and n->>'link' is not null),'approval event informational');
select public.notification_command('preference','{"event":"support_reply","inApp":true,"push":true}');
reset role;
select private.emit_notification('push-test','support_reply',null,current_setting('ns.ticket')::uuid,array['10000000-0000-0000-0000-000000000005'::uuid]);
select pg_temp.ok((select count(*)=1 from private.notification_deliveries),'opted-in delivery queued');
set local role service_role;
select set_config('ns.claim',public.notification_worker('claim')::text,true);
select pg_temp.ok(jsonb_array_length(current_setting('ns.claim')::jsonb)=1,'trusted worker claims one delivery');
select pg_temp.ok(jsonb_array_length(public.notification_worker('claim'))=0,'active lease cannot be claimed twice');
select public.notification_worker('finish',jsonb_build_object('id',current_setting('ns.claim')::jsonb#>>'{0,id}','lease',current_setting('ns.claim')::jsonb#>>'{0,lease}','status',410));
reset role;
select pg_temp.ok((select not active from private.push_subscriptions where endpoint='https://fcm.googleapis.com/fcm/send/synthetic-test'),'expired push subscription disabled');
select pg_temp.ok((select status='failed' from private.notification_deliveries),'failed delivery not falsely sent');
select pg_temp.claim(5);set local role authenticated;
select public.notification_command('subscribe',jsonb_build_object('endpoint','https://fcm.googleapis.com/fcm/send/synthetic-test','p256dh',repeat('a',87),'auth',repeat('b',22)));
select public.notification_command('preference','{"event":"support_reply","inApp":false,"push":true}');
reset role;
select private.emit_notification('push-only-test','support_reply',null,current_setting('ns.ticket')::uuid,array['10000000-0000-0000-0000-000000000005'::uuid]);
select pg_temp.ok((select count(*)=1 from public.notifications n join private.notification_events e on e.id=n.event_id where e.event_key='push-only-test' and not n.in_app),'push preference independent from in-app preference');
set local role authenticated;
select pg_temp.ok((select count(*)=0 from public.notifications n where not n.in_app),'push-only records hidden from direct in-app reads');
select public.notification_command('preference','{"event":"support_reply","inApp":false,"push":false}');
reset role;
select pg_temp.ok((select count(*)=1 from private.notification_deliveries d join public.notifications n on n.id=d.notification_id join private.notification_events e on e.id=n.event_id where e.event_key='push-only-test' and d.status='cancelled'),'push opt-out cancels queued delivery');
-- Actual release/publication operations, not fabricated client events.
select pg_temp.claim(5);set local role authenticated;
select set_config('ns.attempt',public.start_assessment_attempt('a0000000-0000-0000-0000-000000000001')::text,true);
select pg_temp.ok((select count(*)=0 from public.notifications where event_type='exam_released'),'unsubmitted exam produces no result notification');
select public.save_assessment_response(current_setting('ns.attempt')::uuid,'80000000-0000-0000-0000-000000000001','{"option_ids":["90000000-0000-0000-0000-000000000001"]}');
select public.submit_assessment_attempt(current_setting('ns.attempt')::uuid);
select pg_temp.ok((select count(*)=1 from public.notifications where event_type='exam_released'),'actual objective release creates notification');
select pg_temp.ok((select count(*)=1 from jsonb_array_elements(public.notification_command('list')->'rows') n where n->>'event_type'='exam_released' and n->>'link'='/exams/a0000000-0000-0000-0000-000000000001'),'released exam link authorized');
select public.submit_assessment_attempt(current_setting('ns.attempt')::uuid);
select pg_temp.ok((select count(*)=1 from public.notifications where event_type='exam_released'),'duplicate submission does not duplicate release');
select pg_temp.claim(2);
select set_config('ns.group',public.group_command(null,'create',null,'{"offeringId":"60000000-0000-0000-0000-000000000001","name":"Notification test","mode":"online","joinUrl":"https://meet.example.com/room"}')->>'id',true);
select public.group_command(current_setting('ns.group')::uuid,'add',1,'{"userId":"10000000-0000-0000-0000-000000000005"}');
select set_config('ns.session',public.group_command(current_setting('ns.group')::uuid,'one-off',2,jsonb_build_object('title','Notification session','startsAt',clock_timestamp()+interval '5 minutes','endsAt',clock_timestamp()+interval '65 minutes'))->>'sessionId',true);
select pg_temp.claim(5);
select pg_temp.ok((select count(*)=1 from public.notifications where event_type='session_details'),'real online session details event');
select pg_temp.ok((select count(*)=1 from jsonb_array_elements(public.notification_command('list')->'rows') n where n->>'event_type'='session_details' and n->>'link'='/groups'),'group link authorized');
reset role;set local role service_role;
select public.notification_worker('sweep');select public.notification_worker('sweep');
reset role;
select pg_temp.ok((select count(*)=1 from public.notifications n join private.notification_events e on e.id=n.event_id where e.event_key like 'reminder:'||current_setting('ns.session')||':%'),'due reminders deduplicate repeated worker sweep');
-- Homework release remains separate from submission/manual grading.
select pg_temp.claim(2);set local role authenticated;
select set_config('ns.hw',public.save_homework(null,'60000000-0000-0000-0000-000000000001','50000000-0000-0000-0000-000000000001',null,null,'{"title":"Notification homework","instructions":"","mode":"PLATFORM_QUESTIONS","published":true,"rules":{"deadline":"2099-01-01T00:00:00Z"},"usesMarks":true,"filePoints":5,"modelAnswer":"","solutionVideo":"","solutionVideoId":null,"referenceIds":[],"solutionIds":[],"questions":[{"id":"b1000000-0000-0000-0000-000000000077","type":"essay","text":"Explain","imageId":null,"points":5,"responseMode":"text","options":[],"correctIds":[],"modelAnswer":""}]}')::text,true);
select pg_temp.claim(5);
select set_config('ns.sub',public.homework_work(current_setting('ns.hw')::uuid,'start')->>'id',true);
select public.homework_work(current_setting('ns.hw')::uuid,'save',current_setting('ns.sub')::uuid,0,'{"answers":[{"questionId":"b1000000-0000-0000-0000-000000000077","optionIds":[],"text":"An explanation","fileIds":[]}],"fileIds":[]}');
select public.homework_work(current_setting('ns.hw')::uuid,'submit',current_setting('ns.sub')::uuid,1);
select pg_temp.ok((select count(*)=0 from public.notifications where event_type='homework_released'),'submitted homework does not reveal a correction');
select pg_temp.claim(2);
select public.homework_work(current_setting('ns.hw')::uuid,'grade',current_setting('ns.sub')::uuid,0,'{"marks":[{"questionId":"b1000000-0000-0000-0000-000000000077","points":4,"feedback":"Reviewed"}],"feedback":"Good"}');
select public.homework_work(current_setting('ns.hw')::uuid,'release',current_setting('ns.sub')::uuid,1,'{"status":"approved"}');
select pg_temp.claim(5);
select pg_temp.ok((select count(*)=1 from public.notifications where event_type='homework_released'),'actual homework feedback release creates event');
reset role;
update public.enrollments set status='suspended' where user_id='10000000-0000-0000-0000-000000000005' and offering_id='60000000-0000-0000-0000-000000000001';
update public.enrollments set status='active' where user_id='10000000-0000-0000-0000-000000000005' and offering_id='60000000-0000-0000-0000-000000000001';
select pg_temp.ok((select count(*)=current_setting('ns.initial_approved')::int+2 from public.notifications where event_type='account_approved'),'actual enrollment activation creates access-approved event');
-- Platform operator is explicitly provisioned, never inferred from a teacher/global role claim.
select pg_temp.claim(5);set local role authenticated;
select set_config('ns.platform',public.support_command('create',null,null,gen_random_uuid(),'{"organizationId":null,"category":"account","subject":"Platform help","body":"Synthetic"}')->>'id',true);
select pg_temp.claim(1);
select pg_temp.denied($q$select public.support_command('get',current_setting('ns.platform')::uuid)$q$,'42501','organization owner cannot see platform queue');
select pg_temp.claim(2);
select pg_temp.denied($q$select public.support_command('get',current_setting('ns.platform')::uuid)$q$,'42501','assigned organization support cannot see platform queue');
reset role;
insert into private.support_operators(user_id) values('10000000-0000-0000-0000-000000000004');
select pg_temp.claim(4);set local role authenticated;
select pg_temp.ok((public.support_command('get',current_setting('ns.platform')::uuid)->>'staff')::boolean,'trusted provisioned platform operator sees platform ticket');
select pg_temp.ok((select count(*)=0 from public.courses where id='30000000-0000-0000-0000-000000000002'),'platform support grants no cross-tenant academic privileges');
reset role;update private.support_operators set active=false where user_id='10000000-0000-0000-0000-000000000004';set local role authenticated;
select pg_temp.denied($q$select public.support_command('get',current_setting('ns.platform')::uuid)$q$,'42501','operator revocation effective immediately');
reset role;update private.organization_support_staff set active=false where organization_id='20000000-0000-0000-0000-000000000001';select pg_temp.claim(2);set local role authenticated;
select pg_temp.denied($q$select public.support_command('get',current_setting('ns.ticket')::uuid)$q$,'42501','organization support revocation effective immediately');
reset role;
select pg_temp.ok(not exists(select 1 from public.notifications n where to_jsonb(n)::text ~ 'score|correct_answer|feedback|points'),'notification rows contain no grading payload');
select count(*) notifications_support_tests from pg_temp.ns_checks;
rollback;
